// Memeriksa kiriman backend sebelum diteruskan ke Meta.
//
// Backend Go sudah membakukan nomornya lewat nomorWaKirim() sebelum
// disimpan, jadi yang masuk semestinya sudah berbentuk 62xxx. Tetap
// diperiksa ulang di sini: notifikasi lama yang tersimpan sebelum
// pembakuan itu ada, dan satu nomor salah bentuk membuat Meta menolak
// seluruh permintaannya dengan pesan yang tidak menerangkan apa-apa.

const keluar = [];

for (const butir of $input.all()) {
  const badan = butir.json.body ?? butir.json;

  const nomorMentah = String(badan.to ?? '').trim();
  const pesan = String(badan.message ?? '').trim();

  // Hanya angka, lalu dipaksa berawalan kode negara.
  let nomor = nomorMentah.replace(/[^0-9]/g, '');
  if (nomor.startsWith('0')) nomor = '62' + nomor.slice(1);
  else if (nomor && !nomor.startsWith('62')) nomor = '62' + nomor;

  const salah = [];
  if (!nomor) salah.push('nomor tujuan kosong');
  else if (nomor.length < 10 || nomor.length > 15) salah.push('panjang nomor tidak masuk akal: ' + nomor.length + ' angka');
  if (!pesan) salah.push('isi pesan kosong');
  else if (pesan.length > 4096) salah.push('pesan melebihi 4096 aksara');

  keluar.push({ json: { nomor, pesan, sah: salah.length === 0, sebab: salah.join('; ') } });
}

return keluar;
